using System;using System.Collections.Generic;using System.Data.SqlClient;
namespace AshkanPharmacy.Core { public sealed class SearchHit {public string Type{get;set;}public string Title{get;set;}public string Detail{get;set;}}
 public static class GlobalSearchService { public static List<SearchHit> Search(string term){var a=new List<SearchHit>();if(string.IsNullOrWhiteSpace(term)||!Database.IsAvailable)return a;using(var c=Database.Open()){try{using(var q=new SqlCommand("SELECT TOP 8 'Medicine',NameEn,Barcode FROM dbo.Medicines WHERE NameEn LIKE @x OR NameFa LIKE @x OR Barcode LIKE @x",c)){q.Parameters.AddWithValue("@x","%"+term+"%");using(var r=q.ExecuteReader())while(r.Read())a.Add(new SearchHit{Type=r.GetString(0),Title=r.IsDBNull(1)?"":r.GetString(1),Detail=r.IsDBNull(2)?"":r.GetString(2)});}}catch{}try{using(var q=new SqlCommand("SELECT TOP 8 'Patient',FullName,NationalCode FROM dbo.PatientProfiles WHERE FullName LIKE @x OR NationalCode LIKE @x",c)){q.Parameters.AddWithValue("@x","%"+term+"%");using(var r=q.ExecuteReader())while(r.Read())a.Add(new SearchHit{Type=r.GetString(0),Title=r.GetString(1),Detail=r.IsDBNull(2)?"":r.GetString(2)});}}catch{}}return a;} } }